document.addEventListener('DOMContentLoaded', () => {
  const carousels = document.querySelectorAll('.alert-carousel--carousel');
  carousels.forEach(carousel => {
    new Splide(carousel, {
      type: 'loop',
      perPage: 1,
      perMove: 1,
      arrows: true,
      pagination: true,
      drag: true,
      autoplay: false,
      speed: 600
    }).mount();
  });
});